37	// Three alike components are priced as one building block instead of
38	// individually. Only the all-alike case is implemented; mixed and larger
39	// groups stay unwritten until a test asks.
40	const basePriceOf = (items: Item[]): number => {
41	  const isBuildingBlock =
42	    items.length === BUILDING_BLOCK_SIZE && items.every((item) => item.type === items[0].type);
43	
44	  if (isBuildingBlock) return BUILDING_BLOCK_BASE_PRICE;
45	
46	  return items.reduce((total, item) => total + BASE_PRICE_BY_TYPE[item.type], 0);
47	};
