49	// Math.round only clears the float artifact in 100 × 1.1 = 110.00000000000001;
50	// no test yet lands on a half-way value, so the rounding *direction* stays
51	// unspecified until the "rounds in MHPCO's favor" test pins it.
52	const quoteStep = (step: Step): StepResult => ({
53	  premium:
54	    Math.round(basePriceOf(step.items!) * FIRST_INSURANCE_MULTIPLIER) + CONTRACT_FEE,
55	});
56	
57	export const runScenario = (scenario: Scenario): ScenarioResult => ({
58	  results: scenario.steps.map(quoteStep),
59	});
