const allAlike = (items: Item[]): boolean =>
  items.every((item) => item.type === items[0].type);

// Only the exactly-three-alike case is implemented; mixed lists and larger
// groups stay unwritten until a test asks.
const isBuildingBlock = (items: Item[]): boolean =>
  items.length === BUILDING_BLOCK_SIZE && allAlike(items);

const sumOfIndividualPrices = (items: Item[]): number =>
  items.reduce((total, item) => total + BASE_PRICE_BY_TYPE[item.type], 0);

// Three alike components are priced as one building block instead of individually.
const basePriceOf = (items: Item[]): number =>
  isBuildingBlock(items) ? BUILDING_BLOCK_BASE_PRICE : sumOfIndividualPrices(items);
